### 3. Core Method Signatures and Service API

```rust
impl TerminalService {
    /// Initialize the terminal service with shared subsystem handles
    pub fn new(
        pty_manager: Arc<PtyManager>,
        workspace_registry: Arc<WorkspaceRegistry>,
    ) -> Self;

    /// Spawns a new terminal session within a resolved workspace/worktree target.
    ///
    /// 1. Resolves target CWD & canonical workspace safety boundary.
    /// 2. Acquires WriterLeaseGuard on the worktree.
    /// 3. Spawns PTY child process via PtyManager.
    /// 4. Initializes SessionOutputHub with bounded replay ring buffer.
    /// 5. Spawns background pump routing PTY chunks to the SessionOutputHub.
    /// 6. Emits TerminalLifecycleState::Started.
    pub async fn spawn(
        &self,
        workspace_id: &str,
        worktree: Option<&WorktreeIdentity>,
        cols: u16,
        rows: u16,
    ) -> Result<TerminalSessionInfo, TerminalServiceError>;

    /// Lists all active sessions with sanitized metadata (no leaking raw secrets/paths to remote DTOs).
    pub fn list_sessions(&self) -> Vec<TerminalSessionInfo>;

    /// Fetches session info by ID.
    pub fn get_session(&self, session_id: &str) -> Option<TerminalSessionInfo>;

    /// Attaches a consumer (Tauri desktop listener or Remote WebSocket connection)
    /// to an existing session.
    ///
    /// Sequence to prevent output gaps/races:
    /// 1. Subscribe to `broadcast::Receiver<Bytes>`.
    /// 2. Take atomic snapshot of `BoundedReplayBuffer`.
    /// 3. Return `TerminalAttachment` containing history + live receiver.
    pub fn attach(
        &self,
        session_id: &str,
    ) -> Result<TerminalAttachment, TerminalServiceError>;

    /// Writes raw terminal input bytes (from keyboard / remote client) to the PTY.
    pub fn write(
        &self,
        session_id: &str,
        data: &[u8],
    ) -> Result<(), TerminalServiceError>;

    /// Resizes the terminal window dimensions.
    pub fn resize(
        &self,
        session_id: &str,
        cols: u16,
        rows: u16,
    ) -> Result<(), TerminalServiceError>;

    /// Sends a signal (Interrupt / Terminate / Kill) to the terminal session.
    pub fn signal(
        &self,
        session_id: &str,
        signal: TerminalSignal,
    ) -> Result<(), TerminalServiceError>;

    /// Gracefully closes the session, reaps process, releases writer lease,
    /// tears down hub channels, and broadcasts Exited lifecycle event.
    pub async fn close(
        &self,
        session_id: &str,
    ) -> Result<(), TerminalServiceError>;

    /// Global lifecycle subscription for desktop and remote event streamers.
    pub fn subscribe_lifecycle(&self) -> broadcast::Receiver<TerminalLifecycleEvent>;
}
```

